```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:Jettchen_Gebert's_Story dbr:The_Orplid_Mystery }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL { 
    ?director rdfs:label ?labelName .
    FILTER (lang(?labelName) = "en")
  }
  BIND (COALESCE(?directorName, ?labelName) AS ?directorName)

  # director birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bd1 . }
  OPTIONAL { ?director dbo:birthDate ?bd2 . }
  BIND (COALESCE(?bd1, ?bd2) AS ?birthDate)

  # film label (English)
  OPTIONAL { 
    ?film rdfs:label ?filmLabel .
    FILTER (lang(?filmLabel) = "en")
  }
}
LIMIT 100
```

